"use client";

import { useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation"; // Next.js router
import Link from "next/link"; // Next.js Link
import { useNavigate } from "react-router-dom";
const Login = () => {
    // Initialize with empty strings to avoid 'uncontrolled input' warnings
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState(""); // State to handle login errors
    
    const router = useRouter();

    // const handleSubmit = async (e) => {
    //     e.preventDefault();
    //     setError(""); // Reset error message

    //     try {
    //         const result = await axios.post('http://localhost:5000/login', { email, password });
    //         console.log(result);

    //         // Match this condition to exactly what your backend returns
    //         if (result.data.message === 'Login successful') {
    //             router.push('./profile');
    //         } else {
    //             setError(result.data.message);
    //         }
    //     } catch (err) {
    //         console.error(err);
    //         setError(err.response?.data?.message || "An error occurred during login.");
    //     }
    // };

    //  const navigate = useNavigate();
 
    const handleSubmit = (e) => {
        e.preventDefault();
        axios.post('http://localhost:5000/login', { email, password })
        .then(result => {console.log(result)
            if(result.data.message === 'Login successful') {
                router.push('/profile');
            } else {
                alert(result.data.message);
            }
        })
        .catch(error => console.error(error));
    };

    return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
            <form
                className="bg-white p-8 rounded-2xl shadow-lg w-96"
                onSubmit={handleSubmit}
            >
                <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">
                    LOGIN
                </h2>

                {/* Display Error Message if login fails */}
                {error && (
                    <div className="mb-4 p-2 text-sm text-red-600 bg-red-100 rounded text-center">
                        {error}
                    </div>
                )}

                <div className="mb-4">
                    <label className="block mb-1 text-sm font-medium">
                        Email
                    </label>
                    <input
                        type="email"
                        placeholder="Enter your email"
                        className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
                        onChange={(e) => setEmail(e.target.value)}
                        value={email}
                        required
                    />
                </div>

                <div className="mb-6">
                    <label className="block mb-1 text-sm font-medium">
                        Password
                    </label>
                    <input
                        type="password"
                        placeholder="Enter your password"
                        className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
                        onChange={(e) => setPassword(e.target.value)}
                        value={password}
                        required
                    />
                </div>

                <button
                    type="submit"
                    className="w-full bg-green-500 text-white py-2 rounded-lg hover:bg-green-600 transition font-semibold"
                >
                    Login
                </button>
            </form>

            <p className="text-sm text-center mt-4">
                Don't have an account?{" "}
                <Link href="/signup" className="text-blue-500 hover:underline">
                    Register
                </Link>
            </p>
        </div>
    );
};

export default Login;